<script setup lang="ts">
import HdriEditor from './HdriEditor.vue';
import {computed} from 'vue';import {useEditor} from '../stores/editor';import {uid} from '../domain/project';import {bounds} from '../domain/geometry';import type {LightDefinition} from '../domain/types';
const e=useEditor(),light=computed(()=>e.document.lighting.lights.find(l=>l.id===e.selected?.id));
const sunFields=[['sun','Яркость солнца',0,20],['fill','Заполняющий свет',0,10],['azimuth','Направление солнца, °',0,360],['altitude','Высота солнца, °',1,90]] as const;
const lightFields=[['x','Источник X, м'],['y','Источник Y, м'],['z','Источник Z, м'],['intensity','Яркость источника']] as const;
function add(type:'point'|'spot'){const points=e.document.rooms.flatMap(r=>r.points),b=points.length?bounds(points):{minX:0,maxX:4,minZ:0,maxZ:4},x=(b.minX+b.maxX)/2,z=(b.minZ+b.maxZ)/2,id=uid();if(e.edit('Добавить свет',p=>{p.lighting.lights.push({id,name:type==='point'?'Точечный свет':'Направленный свет',type,x,y:Math.max(.1,p.height-.2),z,targetX:x,targetY:0,targetZ:z,color:'#fff1d6',intensity:40,angle:.6});}))e.selected={kind:'light',id};}
function change(fn:(l:LightDefinition)=>void){const id=light.value!.id;e.edit('Изменить свет',p=>fn(p.lighting.lights.find(l=>l.id===id)!));}
</script>
<template><section class="inspector-section"><h2>Освещение</h2><label v-for="[key,label,min,max] in sunFields">{{label}}<input type="number" :min="min" :max="max" step=".1" :value="e.document.lighting[key]" @change="e.edit('Настроить солнце',p=>{p.lighting[key]=Number(($event.target as HTMLInputElement).value)})"></label><HdriEditor/><h3>Источники · {{e.document.lighting.lights.length}} / 16</h3><button :disabled="e.document.lighting.lights.length>=16" @click="add('point')">Добавить точечный свет</button><button :disabled="e.document.lighting.lights.length>=16" @click="add('spot')">Добавить направленный свет</button><button v-for="l in e.document.lighting.lights" :class="['room-item',{active:light?.id===l.id}]" @click="e.selected={kind:'light',id:l.id}">{{l.name}}</button><p class="hint">Качество 1: солнце и заполняющий свет. На уровнях 3–5 тени доступны для первых 1, 2 или 4 источников.</p><template v-if="light"><h3>Выбранный источник</h3><label>Название источника<input :value="light.name" @change="change(l=>l.name=($event.target as HTMLInputElement).value)"></label><label v-for="[key,label] in lightFields">{{label}}<input type="number" step=".1" :value="light[key]" @change="change(l=>{l[key]=Number(($event.target as HTMLInputElement).value)})"></label><label>Цвет света<input type="color" :value="light.color" @change="change(l=>l.color=($event.target as HTMLInputElement).value)"></label><template v-if="light.type==='spot'"><label v-for="[key,label] in ([['targetX','Цель X, м'],['targetY','Цель Y, м'],['targetZ','Цель Z, м']] as const)">{{label}}<input type="number" step=".1" :value="light[key]" @change="change(l=>{l[key]=Number(($event.target as HTMLInputElement).value)})"></label><label>Половина угла конуса, °<input type="number" min="1" max="89" :value="Number((light.angle*180/Math.PI).toFixed(1))" @change="change(l=>l.angle=Number(($event.target as HTMLInputElement).value)*Math.PI/180)"></label></template><button class="danger" @click="e.removeSelected">Удалить источник</button></template></section></template>
